self.addEventListener('message', event => {
  if (!event.data || !['KNIT_OFFLINE_STATUS', 'KNIT_OFFLINE_PREPARE'].includes(event.data.type) || !event.ports || !event.ports[0]) return;
  const port = event.ports[0];
  event.waitUntil((async () => {
    let ready = false;
    try {
      const cache = await caches.open(CACHE_NAME);
      if (event.data.type === 'KNIT_OFFLINE_PREPARE') await fillMissing(cache);
      ready = await completeCache(cache);
    } catch (_) {
      // Repair preserves usable entries. A failed check or repair must never claim offline readiness.
    }
    port.postMessage({ type: 'KNIT_OFFLINE_STATUS', ready, version: OFFLINE_VERSION, assetCount: OFFLINE_ASSETS.length });
  })());
});
